function canonicalStamp(v){
  const n=normText(v||'');
  if(!n||n==='none'||n==='nessuno')return 'None';
  if(n.includes('play')||n.includes('player reward')||n.includes('prize pack'))return 'Play! Pokémon';
  if(n.includes('pokemon day'))return 'Pokémon Day';
  if(n.includes('30 anniversario')||n.includes('30th celebration')||n.includes('30 celebration'))return '30° Anniversario';
  if(n.includes('pokemon center'))return 'Pokémon Center';
  if(n.includes('pre-release')||n.includes('prerelease'))return 'Pre-release';
  if(n.includes('staff'))return 'Staff';
  if(n.includes('set stamp')||n.includes('set-promo'))return 'Set Stamp';
  if(n.includes('gamestop'))return 'GameStop';
  return v||'Altro';
}
